        long a = reader.nextLong();
        long b = reader.nextLong();

        System.out.println(f(a, b));

    }

    static long f(long a, long b) {

        if (a == 1)
            return b;
        if (b == 1)
            return a;

        if (a < b) {
            long t = a;
            a = b;
            b = t;
        }
        return a / b + f(b, a % b);
    }


