		int[] array, sTree, lazy;
		boolean[] isLeaf;

		SegmentTree(int[] in) {
			array = in;
			N = in.length - 1;
			sTree = new int[N << 1]; // no. of nodes = 2*N - 1, we add one to cross out index zero
			lazy = new int[N << 1];
			isLeaf = new boolean[N << 1];
