		void build(int node, int b, int e) // O(n)
		{
			if (b == e) {
				sTree[node] = array[b];
				isLeaf[node] = true;
			} else {
				int mid = b + e >> 1;
				build(node << 1, b, mid);
				build(node << 1 | 1, mid + 1, e);
				sTree[node] = (sTree[node << 1] + sTree[node << 1 | 1]) % 2010;
			}
