def main():
    input = sys.stdin.read
    data = input().split()
    str_input = data[0]
    mod = int(data[1])

    magic = [[[0] * mod for _ in range(10)] for _ in range(20)]
    pow_ = 1

    for a in range(20):
        for b in range(10):
            for c in range(mod):
                magic[a][b][c] = (pow_ * b + c) % mod
        pow_ = (pow_ * 10) % mod

    N = len(str_input)
    array = [int(c) for c in str_input]
    freq = [0] * 10

    for a in array:
        freq[a] += 1

    array.sort()
    memo = [[-1] * (1 << N) for _ in range(mod)]

    def DP(mask, remain):
        if memo[remain][mask] != -1:
            return memo[remain][mask]
        if mask == (1 << N) - 1:
            return 1 if remain == 0 else 0

        ans = 0
        for a in range(N):
            if not (mask >> a) & 1:
                if bin(mask).count('1') == 0 and array[a] == 0:
                    continue
                if a > 0 and (mask >> (a - 1) & 1) == 0 and array[a] == array[a - 1]:
                    continue
                ans += DP(mask + (1 << a), magic[N - bin(mask).count('1') - 1][array[a]][remain])

        memo[remain][mask] = ans
        return ans

    ways = DP(0, 0)

    factorial = [1] * 20
    for a in range(1, 20):
        factorial[a] = factorial[a - 1] * a

    bad = 1
    for a in range(10):
